"use client"

import * as React from "react"
import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { BadgeCounter } from "./badge"
import { Skeleton } from "./skeleton"

type CollapsibleAppearance = "row" | "inline"
type CollapsibleIndicator = "button" | "chevron"
type CollapsibleContentAlign = "start" | "title"

const CollapsibleContext = React.createContext<{
  appearance: CollapsibleAppearance | undefined
  nested: boolean
}>({
  appearance: undefined,
  nested: false,
})

const CollapsibleBodyContext = React.createContext<boolean>(false)

function Collapsible({
  appearance,
  ...props
}: CollapsiblePrimitive.Root.Props & { appearance?: CollapsibleAppearance }) {
  const nested = React.useContext(CollapsibleBodyContext)

  return (
    <CollapsibleContext.Provider value={{ appearance, nested }}>
      <CollapsiblePrimitive.Root
        data-slot="collapsible"
        data-appearance={appearance}
        {...props}
      />
    </CollapsibleContext.Provider>
  )
}

function CollapsibleTrigger({
  className,
  children,
  icon,
  description,
  summary,
  count,
  indicator,
  ...props
}: CollapsiblePrimitive.Trigger.Props & {
  /** Optional leading decorative icon. */
  icon?: React.ReactNode
  /** Optional second line under the label. */
  description?: React.ReactNode
  /** Shown only while the panel is closed. */
  summary?: React.ReactNode
  /** Renders a badge counter. */
  count?: number
  /** "button" = the Plus/Minus box, "chevron" = a chevron that flips. */
  indicator?: CollapsibleIndicator
}) {
  const { appearance } = React.useContext(CollapsibleContext)

  const legacy =
    appearance === undefined &&
    !icon &&
    !description &&
    !summary &&
    count === undefined &&
    (indicator === undefined || indicator === "button")

  if (legacy) {
    return (
      <CollapsiblePrimitive.Trigger
        data-slot="collapsible-trigger"
        className={cn(
          "group/collapsible-trigger flex w-full items-center justify-between gap-4 rounded-md text-start text-sm font-medium text-foreground outline-none focus-ring",
          className
        )}
        {...props}
      >
        {children}
        <span className="flex size-5 shrink-0 items-center justify-center rounded-md border border-border bg-card text-text-secondary">
          <Icon name="plus" className="size-2.5 group-data-[panel-open]/collapsible-trigger:hidden" />
          <Icon name="minus" className="hidden size-2.5 group-data-[panel-open]/collapsible-trigger:block" />
        </span>
      </CollapsiblePrimitive.Trigger>
    )
  }

  const resolvedIndicator = indicator ?? (appearance === undefined ? "button" : "chevron")

  return (
    <CollapsiblePrimitive.Trigger
      data-slot="collapsible-trigger"
      data-appearance={appearance}
      className={cn(
        // The transparent border keeps the outer size stable, so the indigo
        // focus ring can draw on it without shifting the layout.
        "group/collapsible-trigger flex items-center rounded-md text-start text-sm font-medium border border-transparent focus-ring transition-colors duration-fast ease-move hover:bg-bg-page active:bg-bg-subtle data-[disabled]:opacity-40 data-[disabled]:hover:bg-transparent",
        appearance === "inline"
          ? "w-fit max-w-full gap-1 px-[11px] py-[5px] text-text-link"
          : "w-full min-w-0 gap-2 px-[11px] py-[7px] text-foreground",
        className
      )}
      {...props}
    >
      {icon && (
        <span
          aria-hidden
          className="flex shrink-0 text-foreground [&_svg]:size-4"
        >
          {icon}
        </span>
      )}
      {description ? (
        <span className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span>{children}</span>
          <span className="text-xs font-normal text-text-secondary">{description}</span>
        </span>
      ) : (
        <span className={cn("min-w-0", appearance !== "inline" && "flex-1")}>
          {children}
        </span>
      )}
      {summary && (
        <span className="shrink-0 text-xs font-normal text-text-secondary group-data-[panel-open]/collapsible-trigger:hidden">
          {summary}
        </span>
      )}
      {count !== undefined && <BadgeCounter count={count} className="text-text-secondary" />}
      {resolvedIndicator === "chevron" ? (
        <Icon
          name="chevronDown"
          aria-hidden
          className="size-4 shrink-0 transition-transform duration-base ease-move group-data-[panel-open]/collapsible-trigger:rotate-180"
        />
      ) : (
        <span className="flex size-5 shrink-0 items-center justify-center rounded-md border border-border bg-card text-text-secondary">
          <Icon name="plus" className="size-2.5 group-data-[panel-open]/collapsible-trigger:hidden" />
          <Icon name="minus" className="hidden size-2.5 group-data-[panel-open]/collapsible-trigger:block" />
        </span>
      )}
    </CollapsiblePrimitive.Trigger>
  )
}

function CollapsibleContent({
  className,
  children,
  align = "start",
  ...props
}: CollapsiblePrimitive.Panel.Props & { align?: CollapsibleContentAlign }) {
  const { appearance, nested } = React.useContext(CollapsibleContext)

  // Same technique as the Accordion panel: the row animates between 0fr and
  // 1fr, the clip sits on its child and the padding one level further in, so
  // the padding shrinks away with the content. A padding on the panel itself
  // (or a measured height) would stay behind until the panel is hidden, and
  // the row would jump at the very end of closing.
  return (
    <CollapsiblePrimitive.Panel
      data-slot="collapsible-content"
      className={cn(
        // transition-duration only: the duration-base utility also sets animation-duration, which Base UI reads as a keyframe animation on an open panel
        "grid grid-rows-[1fr] text-sm text-text-secondary transition-[grid-template-rows] [transition-duration:var(--duration-base)] ease-entrance data-[ending-style]:grid-rows-[0fr] data-[starting-style]:grid-rows-[0fr]",
        className
      )}
      {...props}
    >
      <div className="min-h-0 overflow-hidden">
        <div
          className={cn(
            appearance === undefined
              ? "pt-4"
              : nested
                ? cn("px-3 pt-4 pb-3", align === "title" && "ps-9")
                : cn("px-3 pt-6 pb-3", align === "title" && "ps-9")
          )}
        >
          <CollapsibleBodyContext.Provider value={true}>
            {children}
          </CollapsibleBodyContext.Provider>
        </div>
      </div>
    </CollapsiblePrimitive.Panel>
  )
}

/**
 * Put the `CollapsibleTrigger` as children and a button (for example a Plain
 * small Button "Edit") as `action`. It sits inside `Collapsible`, around the
 * trigger only (the panel stays a sibling below the row).
 */
function CollapsibleRow({
  action,
  className,
  children,
}: {
  action?: React.ReactNode
  className?: string
  children: React.ReactNode
}) {
  return (
    <div
      data-slot="collapsible-row"
      className={cn("flex items-center gap-1", className)}
    >
      <div className="min-w-0 flex-1">{children}</div>
      {action}
    </div>
  )
}

function CollapsibleFeedback({
  kind,
  title,
  description,
  action,
  loadingLabel,
  className,
}: {
  kind: "loading" | "empty" | "error"
  title?: React.ReactNode
  description?: React.ReactNode
  action?: React.ReactNode
  loadingLabel?: string
  className?: string
}) {
  if (kind === "loading") {
    return (
      <div
        data-slot="collapsible-feedback"
        data-kind="loading"
        role="status"
        aria-busy="true"
        className={cn("flex flex-col gap-0.5", className)}
      >
        <div className="flex flex-col gap-2">
          <Skeleton className="h-2.5 w-full" />
          <Skeleton className="h-2.5 w-4/5" />
          <Skeleton className="h-2.5 w-3/5" />
        </div>
        <p className="pt-1 text-xs">{loadingLabel ?? "Loading…"}</p>
      </div>
    )
  }

  if (kind === "empty") {
    return (
      <div
        data-slot="collapsible-feedback"
        data-kind="empty"
        className={cn("flex flex-col gap-0.5", className)}
      >
        {title && <p className="text-sm font-medium text-foreground">{title}</p>}
        {description && <p className="text-xs">{description}</p>}
        {action}
      </div>
    )
  }

  return (
    <div
      data-slot="collapsible-feedback"
      data-kind="error"
      role="alert"
      className={cn("flex flex-col gap-0.5", className)}
    >
      {title && (
        <div className="flex items-center gap-2">
          <Icon name="warning" className="size-4 text-error" aria-hidden />
          <span className="text-sm font-medium text-foreground">{title}</span>
        </div>
      )}
      {description && <p className="text-xs">{description}</p>}
      {action}
    </div>
  )
}

export {
  Collapsible,
  CollapsibleTrigger,
  CollapsibleContent,
  CollapsibleRow,
  CollapsibleFeedback,
}
export type { CollapsibleAppearance, CollapsibleIndicator, CollapsibleContentAlign }

import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const skeletonVariants = cva(
  // Shimmer wave instead of a plain pulse: a soft highlight sweeps across each
  // placeholder every 1.8 s (keyframes in styles.css, off for reduced motion).
  "relative isolate overflow-hidden bg-muted before:absolute before:inset-0 before:-translate-x-full before:bg-gradient-to-r before:from-transparent before:via-foreground/6 before:to-transparent before:animate-shimmer motion-reduce:before:animate-none dark:before:via-foreground/10",
  {
  variants: {
    variant: {
      text: "h-3.5 w-full rounded-sm",
      title: "h-5 w-2/3 rounded-sm",
      avatar: "size-10 rounded-full",
      block: "h-[100px] w-full rounded-md",
    },
  },
  defaultVariants: {
    variant: "block",
  },
})

function Skeleton({
  className,
  variant,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof skeletonVariants>) {
  return (
    <div
      data-slot="skeleton"
      className={cn(skeletonVariants({ variant }), className)}
      {...props}
    />
  )
}

export { Skeleton, skeletonVariants }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon, type IconName } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { opticalCenter } from "@/lib/optical-center"

// Hex per color - the same hue set as the Figma "Badge" component (600 step
// of each Primitives scale). Kept as plain hex (not CSS vars) so color-mix()
// below can compute the light/opacity variants at runtime.
const BADGE_COLORS = {
  blue: "#12AFF0",
  green: "#1AD598",
  red: "#F47690",
  yellow: "#FACA4A",
  purple: "#A584F3",
  indigo: "#555CF3",
  pink: "#FE6BBA",
  orange: "#F3654A",
  alternative: "#6E6D86",
  grey: "#A2A3A3",
  black: "#000000",
  white: "#FFFFFF",
} as const

type BadgeColor = keyof typeof BADGE_COLORS

const badgeVariants = cva(
  cn(
    "group/badge inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border border-transparent font-semibold whitespace-nowrap transition duration-fast ease-entrance [&>svg]:pointer-events-none",
    // Rendered as a button or link, a badge is a chip: it answers the pointer
    // and the keyboard like any other control.
    //
    // The hover cue is a ring in the label's own colour, not a brightness
    // filter. brightness() moves fill and label together, and because the label
    // polarity differs per colour — a deep hue on a bright fill in light mode,
    // white on indigo and alternative in dark mode — no single factor is safe in
    // both directions: brightness-95/125 measured 3.40:1 on dark alternative,
    // 3.81:1 on dark indigo and 4.44:1 on light orange, and the factors that
    // clear AA everywhere (98%/106%) are too small to see. A ring changes
    // nothing about the label's backdrop, so contrast is unaffected whatever the
    // colour. See /scripts/contrast-audit.mjs, which reads this hover treatment
    // out of this file.
    "[&:is(button,a)]:cursor-pointer [&:is(button,a)]:outline-none [&:is(button,a)]:hover:ring-2 [&:is(button,a)]:hover:ring-current/30 [&:is(button,a)]:active:scale-95 motion-reduce:[&:is(button,a)]:active:scale-100 [&:is(button,a)]:focus-ring"
  ),
  {
    variants: {
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
      size: {
        sm: "h-5 gap-1 px-2 text-xs [&>svg]:size-3!",
        md: "h-6 gap-1.5 px-2.5 text-sm [&>svg]:size-3.5!",
      },
    },
    defaultVariants: {
      shape: "rounded",
      size: "sm",
    },
  }
)

type BadgeStyle = "plain" | "light" | "light_border" | "border_color" | "border_grey" | "ghost"

// Hues that have a Figma tint pair (`tint/<hue>` surface + `tint-text/<hue>`
// text, both mode-aware). Grey, black and white have none and fall back to
// color-mix() below.
const TINTED: readonly BadgeColor[] = ["blue", "green", "red", "yellow", "purple", "indigo", "pink", "orange", "alternative"]

// Text on a solid fill: white on every hue (owner decision Nov 17 2026: white text on solid colour, never black). The one exception is the white badge, whose fill is white itself, so it keeps black text.
const SOLID_TEXT_DARK: readonly BadgeColor[] = ["white"]

// The two achromatic badges are spelled out in Figma rather than derived: a
// black badge pales to the grey scale, a white one to the surface grey — a
// color-mix of #000 or #FFF lands somewhere else entirely.
// `text` sits on the badge's own fill; `ink` sits on the card or on nothing at
// all (outline, ghost), so it has to follow the mode — pure black there would
// vanish into a dark card.
const ACHROMATIC: Partial<Record<BadgeColor, { bg: string; text: string; ink: string; border: string }>> = {
  black: { bg: "var(--dark-200)", text: "#000000", ink: "var(--foreground)", border: "var(--dark-300)" },
  white: { bg: "var(--muted)", text: "var(--foreground)", ink: "var(--foreground)", border: "var(--border-control)" },
  // Grey has no tint pair; its 600 hue (#A2A3A3) is a fill colour, too pale
  // for a label on white. Text takes the tertiary text token instead (AA in
  // both modes), the surface keeps the grey hue.
  grey: {
    // 10 % (not 16 %) keeps the tertiary text at 4.7:1 on the surface — 16 % measured 4.46:1
    bg: "color-mix(in srgb, #A2A3A3 10%, var(--card))",
    text: "var(--text-tertiary)",
    ink: "var(--text-tertiary)",
    border: "var(--border-control)",
  },
}

// Figma Badge / Plain: the label sits on the page, not on a tint, so it takes the semantic text token
// (link, success, error) where one exists and the hue's tint-text everywhere else.
const GHOST_TEXT: Partial<Record<BadgeColor, string>> = {
  indigo: "var(--text-link)",
  green: "var(--text-success)",
  red: "var(--text-error)",
}

function styleToCss(color: BadgeColor, style: BadgeStyle) {
  const hex = BADGE_COLORS[color]
  const tinted = TINTED.includes(color)
  const flat = ACHROMATIC[color]
  const tintBg = flat ? flat.bg : tinted ? `var(--tint-${color})` : `color-mix(in srgb, ${hex} 12%, var(--card))`
  const tintText = flat ? flat.text : tinted ? `var(--tint-text-${color})` : hex === "#FFFFFF" ? "#000000" : hex
  const inkText = flat ? flat.ink : tintText
  const tintBorder = flat
    ? flat.border
    : tinted
      ? `color-mix(in srgb, var(--tint-text-${color}) 40%, var(--card))`
      : `color-mix(in srgb, ${hex} 40%, var(--card))`
  // Figma Badge / Outline: the rim is the tint-text token of the hue itself (a variable, not a blend).
  const outlineBorder = flat ? flat.border : tinted ? `var(--tint-text-${color})` : tintBorder
  switch (style) {
    case "plain":
      return {
        background: hex,
        borderColor: hex,
        color: SOLID_TEXT_DARK.includes(color) ? "#000000" : "#FFFFFF",
      }
    case "light":
      return {
        background: tintBg,
        borderColor: "transparent",
        color: tintText,
      }
    case "light_border":
      return {
        background: tintBg,
        borderColor: outlineBorder,
        color: tintText,
      }
    case "border_color":
      return {
        background: "var(--card)",
        borderColor: tintBorder,
        color: inkText,
      }
    case "border_grey":
      return {
        background: "var(--card)",
        borderColor: "var(--border)",
        color: inkText,
      }
    case "ghost":
      return {
        background: "transparent",
        borderColor: "transparent",
        color: GHOST_TEXT[color] ?? inkText,
      }
  }
}

function Badge({
  className,
  shape,
  size = "sm",
  color = "blue",
  badgeStyle = "plain",
  style,
  render,
  dot,
  onRemove,
  removeLabel = "Remove",
  children,
  ...props
}: useRender.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    color?: BadgeColor
    badgeStyle?: BadgeStyle
    dot?: boolean
    onRemove?: () => void
    removeLabel?: string
  }) {
  // Don't render the remove button when the badge is a button/link (`render`),
  // as that would nest interactive elements.
  const removeButton = onRemove && render === undefined ? (
    <button
      type="button"
      data-slot="badge-remove"
      aria-label={removeLabel}
      onClick={onRemove}
      className="relative -me-1 ms-0.5 inline-flex size-4 shrink-0 cursor-pointer after:absolute after:-inset-1 after:content-['']  items-center justify-center rounded-full outline-none transition duration-fast ease-entrance hover:bg-current/15 active:scale-90 motion-reduce:active:scale-100 focus-ring"
    >
      <Icon name="close" aria-hidden="true" className="size-3" />
    </button>
  ) : null

  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(
      {
        className: cn(badgeVariants({ shape, size }), className),
        style: { ...styleToCss(color, badgeStyle), ...style },
        children: (
          <>
            {dot && (
              <span
                data-slot="badge-dot"
                aria-hidden="true"
                className="size-1.5 shrink-0 rounded-full bg-current"
              />
            )}
            {opticalCenter(children)}
            {removeButton}
          </>
        ),
      },
      props
    ),
    render,
    state: {
      slot: "badge",
      color,
      badgeStyle,
      size,
      ...(dot ? { dot: true } : {}),
    },
  })
}

type BadgeCounterTone = "neutral" | "brand" | "danger"

const BADGE_COUNTER_TONE_CLASSES: Record<BadgeCounterTone, string> = {
  neutral: "bg-bg-subtle text-foreground data-[zero]:text-text-tertiary",
  brand: "bg-primary text-primary-foreground",
  danger: "bg-destructive text-destructive-foreground",
}

const BADGE_COUNTER_KIND_CLASSES: Record<"inline" | "overlay", string> = {
  inline: "h-5 min-w-5 px-1.5 text-xs font-medium",
  overlay: "absolute top-0 right-0 z-10 h-4 min-w-4 translate-x-1/2 -translate-y-1/2 px-1 text-[11px] font-medium ring-2 ring-card",
}

function BadgeCounter({
  count,
  max = 99,
  tone = "neutral",
  overlay = false,
  hideZero,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  count: number
  max?: number
  tone?: BadgeCounterTone
  overlay?: boolean
  hideZero?: boolean
}) {
  const resolvedHideZero = hideZero ?? overlay
  const shown = Math.max(0, Math.trunc(count))
  if (shown <= 0 && resolvedHideZero) return null
  const text = shown > max ? `${max}+` : String(shown)

  return (
    <span
      data-slot="badge-counter"
      data-tone={tone}
      data-kind={overlay ? "overlay" : "inline"}
      data-zero={shown === 0 ? "" : undefined}
      className={cn(
        "inline-flex items-center justify-center rounded-full tabular-nums leading-none whitespace-nowrap select-none",
        BADGE_COUNTER_KIND_CLASSES[overlay ? "overlay" : "inline"],
        BADGE_COUNTER_TONE_CLASSES[tone],
        className
      )}
      {...props}
    >
      <span className="optical-center">{text}</span>
    </span>
  )
}

type BadgeIndicatorKind = "unread" | "online" | "away" | "busy" | "offline" | "check" | "warning" | "lock"

const DEFAULT_LABELS: Record<BadgeIndicatorKind, string> = {
  unread: "Unread",
  online: "Online",
  away: "Away",
  busy: "Busy",
  offline: "Offline",
  check: "Done",
  warning: "Warning",
  lock: "Locked",
}

const INDICATOR_CONFIG: Record<
  BadgeIndicatorKind,
  {
    root: string
    size: Record<"sm" | "md", string>
    icon?: IconName
    iconSize: Record<"sm" | "md", string>
    strokeWidth?: number
    fill?: boolean
  }
> = {
  unread: {
    root: "bg-primary",
    size: { sm: "size-2", md: "size-2.5" },
    iconSize: { sm: "", md: "" },
  },
  online: {
    root: "bg-success",
    size: { sm: "size-2", md: "size-2.5" },
    iconSize: { sm: "", md: "" },
  },
  offline: {
    root: "border-[1.5px] border-text-tertiary bg-transparent",
    size: { sm: "size-2", md: "size-2.5" },
    iconSize: { sm: "", md: "" },
  },
  busy: {
    root: "bg-destructive text-destructive-foreground",
    size: { sm: "size-2", md: "size-2.5" },
    icon: "minus",
    iconSize: { sm: "size-1.5", md: "size-2" },
    strokeWidth: 4,
  },
  away: {
    root: "bg-transparent text-brand-quaternary",
    size: { sm: "size-2", md: "size-2.5" },
    icon: "moon",
    iconSize: { sm: "size-2", md: "size-2.5" },
    strokeWidth: 0,
    fill: true,
  },
  check: {
    root: "bg-success text-success-foreground",
    size: { sm: "size-4", md: "size-5" },
    icon: "check",
    iconSize: { sm: "size-2.5", md: "size-3" },
    strokeWidth: 2.5,
  },
  warning: {
    root: "bg-brand-quaternary text-brand-quaternary-foreground",
    size: { sm: "size-4", md: "size-5" },
    icon: "warning",
    iconSize: { sm: "size-2.5", md: "size-3" },
    strokeWidth: 2.5,
  },
  lock: {
    root: "bg-foreground text-background",
    size: { sm: "size-4", md: "size-5" },
    icon: "lock",
    iconSize: { sm: "size-2.5", md: "size-3" },
    strokeWidth: 2.5,
  },
}

function BadgeIndicator({
  kind,
  size = "sm",
  label,
  overlay = false,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  kind: BadgeIndicatorKind
  size?: "sm" | "md"
  label?: string
  overlay?: boolean
}) {
  const config = INDICATOR_CONFIG[kind]

  // Overlay mode requires a relative parent to anchor against.
  return (
    <span
      role="img"
      aria-label={label ?? DEFAULT_LABELS[kind]}
      data-slot="badge-indicator"
      data-kind={kind}
      data-size={size}
      data-overlay={overlay ? "" : undefined}
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded-full",
        overlay && "absolute top-0 right-0 z-10 translate-x-1/2 -translate-y-1/2 ring-2 ring-card",
        config.size[size],
        config.root,
        className
      )}
      {...props}
    >
      {config.icon && (
        <Icon
          name={config.icon}
          aria-hidden="true"
          className={cn(config.iconSize[size], config.fill && "fill-current")}
          strokeWidth={config.strokeWidth}
        />
      )}
    </span>
  )
}

type BadgeProcessingState = "pending" | "success" | "error"

function BadgeProcessing({
  state,
  children,
  ...props
}: Omit<React.ComponentProps<typeof Badge>, "color" | "badgeStyle" | "shape" | "dot" | "onRemove"> & {
  state: BadgeProcessingState
}) {
  const pending = state === "pending"
  const done = state === "success"

  const icon = pending ? (
    <Icon name="spinner" aria-hidden="true" className="animate-spin motion-reduce:animate-none" />
  ) : done ? (
    <Icon name="check" aria-hidden="true" />
  ) : (
    <Icon name="warning" aria-hidden="true" />
  )

  const color = pending ? "blue" : done ? "green" : "red"

  return (
    <Badge
      shape="pill"
      badgeStyle="light"
      color={color}
      data-state={state}
      role="status"
      aria-busy={pending ? true : undefined}
      {...props}
    >
      {icon}
      {children}
    </Badge>
  )
}

